namespace SmallBasic.Utilities.Resources
{
    using System;
    using System.Collections.Concurrent;
    using System.Collections.Generic;
    using System.Globalization;
    using System.Reflection;
    using System.Resources;
    using System.Xml;

    /// <summary>
    /// A resource manager that serves SmallBasicLibrary documentation strings
    /// translated from the SmallBasicHomeSite documentation (embedded as
    /// DocumentationLocales.xml) before falling back to the neutral (English)
    /// resources compiled into this assembly by the classic resx pipeline.
    /// </summary>
    /// <remarks>
    /// The embedded translations are generated by tools/generate-localized-docs.ps1.
    /// Keys that a locale does not provide automatically fall back to English.
    /// </remarks>
    public sealed class LocalizedDocumentationResourceManager : ResourceManager
    {
        private const string LocaleResourceName = "SmallBasic.Utilities.DocumentationLocales.xml";

        private static readonly Lazy<Dictionary<string, Dictionary<string, string>>> LocaleTables =
            new Lazy<Dictionary<string, Dictionary<string, string>>>(LoadLocales);

        // culture-name -> resolved locale name ("" when only English applies).
        private static readonly ConcurrentDictionary<string, string> LocaleByCultureName =
            new ConcurrentDictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        public LocalizedDocumentationResourceManager(string baseName, Assembly assembly)
            : base(baseName, assembly)
        {
        }

        /// <summary>
        /// Resolves the SmallBasic documentation locale for a UI culture,
        /// e.g. zh-CN -> zh-Hans. Returns null for English/invariant cultures.
        /// </summary>
        public static string ResolveLocale(CultureInfo culture)
        {
            if (culture.IsDefault())
            {
                return null;
            }

            var tables = LocaleTables.Value;
            if (tables.IsDefault())
            {
                return null;
            }

            var locale = LocaleByCultureName.GetOrAdd(culture.Name, _ => ResolveLocaleCore(culture, tables));
            return string.IsNullOrEmpty(locale) ? null : locale;
        }

        public override string GetString(string name)
        {
            var localized = LookupLocalized(name, CultureInfo.CurrentUICulture);
            if (!localized.IsDefault())
            {
                return localized;
            }

            return base.GetString(name, CultureInfo.CurrentUICulture);
        }

        public override string GetString(string name, CultureInfo culture)
        {
            var effectiveCulture = culture.IsDefault() ? CultureInfo.CurrentUICulture : culture;
            var localized = LookupLocalized(name, effectiveCulture);
            if (!localized.IsDefault())
            {
                return localized;
            }

            return base.GetString(name, effectiveCulture);
        }

        private static string ResolveLocaleCore(CultureInfo culture, Dictionary<string, Dictionary<string, string>> tables)
        {
            // Walk the culture chain: zh-CN -> zh-Hans, de-DE -> de, pt-BR -> pt-br.
            var current = culture;
            while (!current.IsDefault() && !string.IsNullOrEmpty(current.Name))
            {
                var locale = FindLocale(tables, current.Name);
                if (!locale.IsDefault())
                {
                    return locale;
                }

                current = current.Parent;
            }

            // Chinese requires a script/region distinction that the plain
            // two-letter tag cannot provide, so it stays untranslated.
            var twoLetter = culture.TwoLetterISOLanguageName;
            if (!string.IsNullOrEmpty(twoLetter) && !string.Equals(twoLetter, "zh", StringComparison.OrdinalIgnoreCase))
            {
                return FindLocale(tables, twoLetter) ?? string.Empty;
            }

            return string.Empty;
        }

        private static string FindLocale(Dictionary<string, Dictionary<string, string>> tables, string name)
        {
            foreach (var key in tables.Keys)
            {
                if (string.Equals(key, name, StringComparison.OrdinalIgnoreCase))
                {
                    return key;
                }
            }

            return null;
        }

        private static Dictionary<string, Dictionary<string, string>> LoadLocales()
        {
            try
            {
                var assembly = typeof(LocalizedDocumentationResourceManager).Assembly;
                using (var stream = assembly.GetManifestResourceStream(LocaleResourceName))
                {
                    if (stream.IsDefault())
                    {
                        return null;
                    }

                    var result = new Dictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
                    using (var reader = XmlReader.Create(stream))
                    {
                        Dictionary<string, string> currentStrings = null;
                        while (reader.Read())
                        {
                            if (reader.NodeType != XmlNodeType.Element)
                            {
                                continue;
                            }

                            if (reader.LocalName == "locale")
                            {
                                var name = reader.GetAttribute("name");
                                currentStrings = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                                if (!string.IsNullOrEmpty(name))
                                {
                                    result[name] = currentStrings;
                                }
                            }
                            else if (reader.LocalName == "s" && !currentStrings.IsDefault() && !reader.IsEmptyElement)
                            {
                                var key = reader.GetAttribute("k");
                                var value = reader.ReadElementContentAsString();
                                if (!string.IsNullOrEmpty(key) && !value.IsDefault() && !currentStrings.ContainsKey(key))
                                {
                                    currentStrings[key] = value;
                                }
                            }
                        }
                    }

                    return result.Count > 0 ? result : null;
                }
            }
            catch
            {
                // Localized documentation is optional; English resources always remain.
                return null;
            }
        }

        private static string LookupLocalized(string name, CultureInfo culture)
        {
            var tables = LocaleTables.Value;
            if (tables.IsDefault() || string.IsNullOrEmpty(name))
            {
                return null;
            }

            var locale = ResolveLocale(culture);
            if (locale.IsDefault())
            {
                return null;
            }

            return tables.TryGetValue(locale, out var strings) && strings.TryGetValue(name, out var value)
                ? value
                : null;
        }
    }
}
